CREATE TABLE Operadora ( IdOperadora INT NOT NULL, DeOperadora VARCHAR(45) NULL, PRIMARY KEY (IdOperadora));

CREATE TABLE Reclamacoes ( IdReclamacao INT NOT NULL AUTO_INCREMENT, DeReclamacao VARCHAR(45) NULL, IdOperadora INT NOT NULL, PRIMARY KEY (IdReclamacao), FOREIGN KEY (IdOperadora) REFERENCES Operadora (IdOperadora));

A execução dos comandos SQL precedentes resulta na criação de duas tabelas e no relacionamento descrito no modelo apresentado na figura CB1A5.
